/* The length of the PNG that starts exactly at va in this build, 0 when none does
 * (an unknown build has no images). */
static uint32_t ep147png_len(int build, uintptr_t va) {
    const struct ep147_png *t = 0;
    long n = 0;
    if (build == EPB_V130) {
        t = EP147_PNG_V130;
        n = (long) (sizeof EP147_PNG_V130 / sizeof *EP147_PNG_V130);
    } else if (build == EPB_V200) {
        t = EP147_PNG_V200;
        n = (long) (sizeof EP147_PNG_V200 / sizeof *EP147_PNG_V200);
    }
    long lo = 0, hi = n - 1;
    while (lo <= hi) {
        long mid = lo + (hi - lo) / 2;
        if (t[mid].va == va)
            return t[mid].len;
        if (t[mid].va < va)
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    return 0;
}
